{"command": "cd /tmp/t1 && cat > model.py <<'PYEOF'
import re,sys,json,subprocess

def is_ws(c): return c.isspace()

def tokenize_block(lines):
    """lines: list of content strings (without prefix char, without newline).
    Return list of tokens: (text, line_index, is_newline)"""
    toks=[]
    for li,line in enumerate(lines):
        i=0
        while i < len(line):
            if line[i].isspace():
                j=i
                while j<len(line) and line[j].isspace(): j+=1
                toks.append((line[i:j], li, False)); i=j
            else:
                j=i
                while j<len(line) and not line[j].isspace(): j+=1
                toks.append((line[i:j], li, False)); i=j
        toks.append(('\n', li, True))
    return toks

def runs(ops):
    """ops: list of ('C'|'R'|'A'). merge consecutive same-kind."""
    out=[]
    for o in ops:
        if out and out[-1][0]==o: out[-1][1]+=1
        else: out.append([o,1])
    return out

def build_segments(ta, tb, ops):
    """ta,tb: token lists. ops: list of (kind, count).
    Return list of (line, kind, text) pieces in order, with kind 'C' or 'U'."""
    ia=0; ib=0; pieces=[]
    def emit(line, kind, buf):
        pieces.append([line, kind, buf])
    for kind,cnt in ops:
        if kind=='C':
            buf=''; curline=ta[ia][1] if ia<len(ta) else 0
            for _ in range(cnt):
                t=ta[ia]
                if t[2]:  # newline
                    emit(curline,'C',buf); buf=''; curline=t[1]+1
                else:
                    buf+=t[0]; curline=t[1]
                ia+=1; ib+=1
            emit(curline,'C',buf)
        elif kind=='R':
            buf=''; curline=ta[ia][1] if ia<len(ta) else 0
            for _ in range(cnt):
                t=ta[ia]
                if t[2]:
                    emit(curline,'U',buf); buf=''; curline=t[1]+1
                else:
                    buf+=t[0]; curline=t[1]
                ia+=1
            emit(curline,'U',buf)
        else:
            buf=''; curline=tb[ib][1] if ib<len(tb) else 0
            for _ in range(cnt):
                t=tb[ib]
                if t[2]:
                    emit(curline,'U',buf); buf=''; curline=t[1]+1
                else:
                    buf+=t[0]; curline=t[1]
                ib+=1
            emit(curline,'U',buf)
    return pieces

def lines_of(pieces, nlines):
    """convert pieces to per-line lists of (kind,text); drop empty pieces at start of line"""
    res=[[] for _ in range(nlines)]
    for line,kind,text in pieces:
        if line < nlines:
            lst=res[line]
            # merge with previous if same kind
            if lst and lst[-1][0]==kind: lst[-1]= (kind, lst[-1][1]+text)
            else: lst.append((kind,text))
    return res

# diff algorithms
def lcs_dp_backtrack(a,b,pref_rem=True):
    n=len(a); m=len(b)
    L=[[0]*(m+1) for _ in range(n+1)]
    for i in range(1,n+1):
        ai=a[i-1]
        row=L[i]; prev=L[i-1]
        for j in range(1,m+1):
            if ai==b[j-1]: row[j]=prev[j-1]+1
            else:
                row[j]=prev[j] if prev[j]>=row[j-1] else row[j-1]
    ops=[]
    i=n; j=m
    while i>0 and j>0:
        if a[i-1]==b[j-1]:
            ops.append('C'); i-=1; j-=1
        else:
            if (L[i-1][j] >= L[i][j-1]) == pref_rem:
                ops.append('R'); i-=1
            else:
                ops.append('J'); j-=1
    while i>0: ops.append('R'); i-=1
    while j>0: ops.append('J'); j-=1
    ops.reverse()
    return ops

def myers(a,b,prefer='del'):
    # standard O(ND) with trace; prefer 'del' => when V[k-1]<V[k+1] use k+1 (insert) else deletion...
    n=len(a); m=len(b)
    maxd=n+m
    V={1:0}; trace=[]
    found=False
    for d in range(0,maxd+1):
        trace.append(dict(V))
        for k in range(-d,d+1,2):
            if k==-d or (k!=d and V.get(k-1,-10**9) < V.get(k+1,-10**9)):
                x=V.get(k+1,0)
            else:
                x=V.get(k-1,0)+1
            y=x-k
            while x<n and y<m and a[x]==b[y]:
                x+=1; y+=1
            V[k]=x
            if x>=n and y>=m:
                found=True; break
        if found: break
    # backtrack
    ops=[]
    x=n; y=m
    for d in range(len(trace)-1,0,-1):
        v=trace[d]
        k=x-y
        if k==-d or (k!=d and v.get(k-1,-10**9) < v.get(k+1,-10**9)):
            prevk=k+1
        else:
            prevk=k-1
        prevx=v.get(prevk,0)
        prevy=prevx-prevk
        while x>prevx and y>prevy:
            ops.append('C'); x-=1; y-=1
        if x==prevx:
            while y>prevy: ops.append('J'); y-=1
        else:
            while x>prevx: ops.append('R'); x-=1
    ops.reverse()
    return ops
PYEOF
