    buf=''; curline=toks[idx][1] if idx<len(toks) else 0
    for _ in range(cnt):
        t=toks[idx]
        if t[2]:
            pieces.append((side,curline,kind,buf)); buf=''; curline=t[1]+1
        else:
            buf+=t[0]; curline=t[1]
        idx+=1
    if emission=='nonempty':
        if buf: pieces.append((side,curline,kind,buf))
    else:
        pieces.append((side,curline,kind,buf))
    return idx

def face_of(side,kind,text,last_of_line,line_allws):
    lineface=FG['removed' if side=='R' else 'added']
    ref=REF['removed' if side=='R' else 'added']
    ws = text.strip(WS)==''
    if ws:
        if line_allws: return BGONLY
        if last_of_line and kind=='U': return BGONLY
        return ref if kind=='U' else lineface
    return lineface if kind=='C' else ref

def build(leads_r,toks_r,nr,leads_a,toks_a,na,ops,emission):
    pieces=[]
    ia=0; ib=0
    for kind,cnt in ops:
        if kind=='C':
            ia=emit_pieces(toks_r,ia,cnt,kind,pieces,'R',emission)
            ib=emit_pieces(toks_a,ib,cnt,kind,pieces,'A',emission)
        elif kind=='R':
            ia=emit_pieces(toks_r,ia,cnt,kind,pieces,'R',emission)
        else:
            ib=emit_pieces(toks_a,ib,cnt,kind,pieces,'A',emission)
    segr=[[] for _ in range(nr)]; sega=[[] for _ in range(na)]
    for side,line,kind,text in pieces:
        lst = segr if side=='R' else sega
        if line < len(lst):
            l=lst[line]
            if l and l[-1][0]==kind: l[-1]=(kind,l[-1][1]+text)
            else: l.append((kind,text))
    return segr,sega

