WS=' \t\v\f\r'
def is_ws(c): return c in WS

def tokenize_line_v(content, mode):
    """mode: 'sep' whitespace as separate tokens; returns (lead, tokens)"""
    i=0; n=len(content)
    j=i
    while j<n and is_ws(content[j]): j+=1
    if j>=n:
        return content, []
    lead=content[:j]; rest=content[j:]
    toks=[]; k=0; m=len(rest)
    while k<m:
        if is_ws(rest[k]):
            l=k
            while l<m and is_ws(rest[l]): l+=1
            toks.append(rest[k:l]); k=l
        else:
            l=k
            while l<m and not is_ws(rest[l]): l+=1
            toks.append(rest[k:l]); k=l
    return lead,toks

def tokenize_lines(lines, nlmode='all'):
    """nlmode: 'all' -> NL after every line; 'between' -> NL between lines only; 'none' -> no NL"""
    leads=[]; toks=[]
    for li,c in enumerate(lines):
        lead,t=tokenize_line_v(c,'sep')
        leads.append(lead)
        for tx in t: toks.append((tx,li,False))
        if nlmode=='all' or (nlmode=='between' and li<len(lines)-1):
            toks.append(('\n',li,True))
    return leads,toks

def merge_runs(ops):
    out=[]
    for o in ops:
        if out and out[-1][0]==o: out[-1]=(o,out[-1][1]+1)
        else: out.append((o,1))
    return out

def lcs_dp(a,b,pref='R'):
    n=len(a); m=len(b)
    L=[[0]*(m+1) for _ in range(n+1)]
    for i in range(1,n+1):
        ai=a[i-1]; row=L[i]; prev=L[i-1]
        for j in range(1,m+1):
            if ai==b[j-1]: row[j]=prev[j-1]+1
            elif prev[j]>=row[j-1]: row[j]=prev[j]
            else: row[j]=row[j-1]
    ops=[]; i=n; j=m
    while i>0 and j>0:
        if a[i-1]==b[j-1]: ops.append('C'); i-=1; j-=1
        elif pref=='R' and L[i-1][j]>=L[i][j-1]: ops.append('R'); i-=1
        elif pref=='A' and L[i][j-1]>=L[i-1][j]: ops.append('A'); j-=1
        elif pref=='R': ops.append('A'); j-=1
        else: ops.append('R'); i-=1
    while i>0: ops.append('R'); i-=1
    while j>0: ops.append('A'); j-=1
    ops.reverse(); return ops

def lcs_dp_fwd(a,b,pref='R'):
    """forward backtrack using the DP table: choose to advance so that remaining LCS is max"""
    n=len(a); m=len(b)
    L=[[0]*(m+1) for _ in range(n+1)]
    for i in range(1,n+1):
        ai=a[i-1]; row=L[i]; prev=L[i-1]
        for j in range(1,m+1):
            if ai==b[j-1]: row[j]=prev[j-1]+1
            elif prev[j]>=row[j-1]: row[j]=prev[j]
            else: row[j]=row[j-1]
    ops=[]; i=0; j=0
    while i<n and j<m:
        if a[i]==b[j]: ops.append('C'); i+=1; j+=1; continue
        # choose the branch that keeps the max remaining lcs
        keep_r = L[i+1][j] if i+1<=n else 0
        keep_a = L[i][j+1] if j+1<=m else 0
        if pref=='R':
            if keep_r>=keep_a: ops.append('R'); i+=1
            else: ops.append('A'); j+=1
        else:
            if keep_a>=keep_r: ops.append('A'); j+=1
            else: ops.append('R'); i+=1
    while i<n: ops.append('R'); i+=1
    while j<m: ops.append('A'); j+=1
    return ops

