// diffr reimplementation
use std::collections::HashMap;
use std::io::{Read, Write};

pub const RESET: &str = "\x1b[0m";

// ---------------- colors ----------------

#[derive(Clone, PartialEq, Debug, Copy)]
pub enum Color {
    Named(u8),   // 0..7
    Ansi(u8),    // 0..255
    Rgb(u8, u8, u8),
}

#[derive(Clone, Copy, PartialEq, Debug, Default)]
pub struct Face {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub intense: bool,
    pub none: bool, // "clear all"
}

impl Face {
    pub fn is_empty(&self) -> bool {
        self.fg.is_none() && self.bg.is_none() && !self.bold && !self.dimmed && !self.italic
            && !self.underline && !self.intense && !self.none
    }
    pub fn escape(&self) -> String {
        // order: reset, attributes (bold, dimmed, italic, underline), fg, bg
        let mut s = String::new();
        if self.none {
            return RESET.to_string();
        }
        if self.bold { s.push_str("\x1b[1m"); }
        if self.dimmed { s.push_str("\x1b[2m"); }
