fn emit_pieces(toks: &[Token], idx: usize, cnt: usize, kind: Kind, pieces: &mut Vec<(bool, usize, Kind, String)>, removed: bool) -> usize {
    let mut buf = String::new();
    let mut curline = if idx < toks.len() { toks[idx].line } else { 0 };
    let mut i = idx;
    for _ in 0..cnt {
        let t = &toks[i];
        if t.is_nl {
            pieces.push((removed, curline, kind, buf.clone()));
            buf.clear();
            curline = t.line + 1;
        } else {
            buf.push_str(&t.text);
            curline = t.line;
        }
        i += 1;
    }
    if !buf.is_empty() {
        pieces.push((removed, curline, kind, buf));
    }
    i
}

pub fn build_segments(
    toks_r: &[Token], nr: usize,
    toks_a: &[Token], na: usize,
    ops: &[(Op, usize)],
) -> (Vec<Vec<Segment>>, Vec<Vec<Segment>>) {
    let mut pieces: Vec<(bool, usize, Kind, String)> = Vec::new();
    let mut ia = 0; let mut ib = 0;
    for (op, cnt) in ops {
        match op {
            Op::C => {
                ia = emit_pieces(toks_r, ia, *cnt, Kind::Common, &mut pieces, true);
                ib = emit_pieces(toks_a, ib, *cnt, Kind::Common, &mut pieces, false);
            }
            Op::R => { ia = emit_pieces(toks_r, ia, *cnt, Kind::Unique, &mut pieces, true); }
            Op::A => { ib = emit_pieces(toks_a, ib, *cnt, Kind::Unique, &mut pieces, false); }
        }
    }
    let mut segr: Vec<Vec<Segment>> = vec![Vec::new(); nr];
    let mut sega: Vec<Vec<Segment>> = vec![Vec::new(); na];
    for (removed, line, kind, text) in pieces {
        let lst = if removed { &mut segr } else { &mut sega };
        if line < lst.len() {
            let l = &mut lst[line];
            if let Some(last) = l.last_mut() {
                if last.kind == kind { last.text.push_str(&text); continue; }
            }
            l.push(Segment { kind, text });
        }
    }
    (segr, sega)
}
