use std::collections::HashMap;
use std::io::{Read, Write};

pub const RESET: &str = "\x1b[0m";

// ---------------- colors ----------------

#[derive(Clone, PartialEq, Debug, Copy)]
pub enum Color {
    Named(u8),   // 0..7
    Ansi(u8),    // 0..255
    Rgb(u8, u8, u8),
}

#[derive(Clone, Copy, PartialEq, Debug, Default)]
pub struct Face {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub intense: bool,
    pub none: bool, // "clear all"
}

impl Face {
    pub fn is_empty(&self) -> bool {
        self.fg.is_none() && self.bg.is_none() && !self.bold && !self.dimmed && !self.italic
            && !self.underline && !self.intense && !self.none
    }
    pub fn escape(&self) -> String {
        // order: reset, attributes (bold, dimmed, italic, underline), fg, bg
        let mut s = String::new();
        if self.none {
            return RESET.to_string();
        }
        if self.bold { s.push_str("\x1b[1m"); }
        if self.dimmed { s.push_str("\x1b[2m"); }
        if self.italic { s.push_str("\x1b[3m"); }
        if self.underline { s.push_str("\x1b[4m"); }
        if let Some(fg) = self.fg { s.push_str(&fg_escape(fg, self.intense, false)); }
        if let Some(bg) = self.bg { s.push_str(&fg_escape(bg, self.intense, true)); }
        s
    }
}

fn fg_escape(c: Color, intense: bool, bg: bool) -> String {
    let base = if bg { 40 } else { 30 };
    match c {
        Color::Named(n) => {
            if intense {
                format!("\x1b[{};5;{}m", if bg { 48 } else { 38 }, n + 8)
            } else {
                format!("\x1b[{}m", base + n)
            }
        }
        Color::Ansi(n) => {
            format!("\x1b[{};5;{}m", if bg { 48 } else { 38 }, n)
        }
        Color::Rgb(r, g, b) => {
            format!("\x1b[{};2;{};{};{}m", if bg { 48 } else { 38 }, r, g, b)
        }
    }
}

fn parse_color(s: &str) -> Result<Color, String> {
    match s {
        "black" => Ok(Color::Named(0)),
        "red" => Ok(Color::Named(1)),
        "green" => Ok(Color::Named(2)),
        "yellow" => Ok(Color::Named(3)),
        "blue" => Ok(Color::Named(4)),
        "magenta" => Ok(Color::Named(5)),
        "cyan" => Ok(Color::Named(6)),
        "white" => Ok(Color::Named(7)),
        _ => {}
    }
    // number 0-255 or hex 0x..
    if let Some(rest) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        if let Ok(v) = u32::from_str_radix(rest, 16) {
            if v <= 255 { return Ok(Color::Ansi(v as u8)); }
        }
        return Err(unrecognized_color(s));
    }
    if let Ok(v) = s.parse::<u32>() {
        if v <= 255 { return Ok(Color::Ansi(v as u8)); }
        return Err(format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s));
    }
    if s.contains(',') {
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() == 3 {
            let mut vals = [0u8; 3];
            let mut ok = true;
            for (i, p) in parts.iter().enumerate() {
                match p.trim().parse::<u32>() {
                    Ok(v) if v <= 255 => vals[i] = v as u8,
                    _ => { ok = false; }
                }
            }
            if ok { return Ok(Color::Rgb(vals[0], vals[1], vals[2])); }
        }
        return Err(unrecognized_color(s));
    }
    Err(unrecognized_color(s))
}

