pub const ATTR_NAMES: &str = "foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none";
pub const FACE_NAMES: &str = "added|refine-added|removed|refine-removed";

pub fn parse_color_spec(spec: &str, faces: &mut [Face; 4]) -> Result<(), String> {
    let mut it = spec.split(':');
    let name = it.next().unwrap_or("");
    let idx = match name {
        "added" => 0,
        "refine-added" => 1,
        "removed" => 2,
        "refine-removed" => 3,
        _ => return Err(format!("unexpected face name: got '{}', expected {}", name, FACE_NAMES)),
    };
    let mut face = faces[idx];
    let mut have_fg = false;
    let mut have_bg = false;
    // first attribute must be present
    let mut first = true;
    for attr in it {
        if first {
            match attr {
                "foreground" | "background" | "italic" | "noitalic" | "bold" | "nobold"
                | "dimmed" | "nodimmed" | "intense" | "nointense" | "underline"
                | "nounderline" | "none" => {}
                _ => return Err(format!("unexpected attribute name: got '{}', expected {}", attr, ATTR_NAMES)),
            }
            first = false;
        }
        match attr {
            "foreground" => { have_fg = true; }
            "background" => { have_bg = true; }
            "italic" => face.italic = true,
            "noitalic" => face.italic = false,
            "bold" => face.bold = true,
            "nobold" => face.bold = false,
            "dimmed" => face.dimmed = true,
            "nodimmed" => face.dimmed = false,
            "intense" => face.intense = true,
            "nointense" => face.intense = false,
            "underline" => face.underline = true,
            "nounderline" => face.underline = false,
            "none" => { face = Face { none: true, ..Default::default() }; }
            other => {
                // must be a color value for the pending fg/bg
                let c = parse_color(other)?;
                if have_fg { face.fg = Some(c); have_fg = false; }
                else if have_bg { face.bg = Some(c); have_bg = false; }
                else {
                    return Err(format!("unexpected attribute name: got '{}', expected {}", other, ATTR_NAMES));
                }
            }
        }
    }
    faces[idx] = face;
    Ok(())
}

