// ---------------- tokenizer ----------------

fn is_ws(c: char) -> bool { c.is_whitespace() }

#[derive(Clone, Debug)]
pub struct Token {
    pub text: String,
    pub line: usize,
    pub is_nl: bool,
}

/// Returns (leading whitespace, tokens) for one line content.
/// The leading whitespace is excluded from the token stream.
/// If the content is entirely whitespace, returns (content, empty).
pub fn tokenize_line(content: &str) -> (String, Vec<Token>) {
    let chars: Vec<char> = content.chars().collect();
    let n = chars.len();
    let mut j = 0;
    while j < n && is_ws(chars[j]) { j += 1; }
    if j >= n {
        return (content.to_string(), Vec::new());
    }
    let lead: String = chars[..j].iter().collect();
    let rest: String = chars[j..].iter().collect();
    let mut toks = Vec::new();
    let rc: Vec<char> = rest.chars().collect();
    let m = rc.len();
    let mut k = 0;
    while k < m {
        if is_ws(rc[k]) {
            let l = k;
            while l < m && is_ws(rc[l]) { l += 1; }
            toks.push(Token { text: rc[k..l].iter().collect(), line: 0, is_nl: false });
            k = l;
        } else {
            let l = k;
            while l < m && !is_ws(rc[l]) { l += 1; }
            toks.push(Token { text: rc[k..l].iter().collect(), line: 0, is_nl: false });
            k = l;
        }
    }
    (lead, toks)
}

pub fn tokenize_lines(lines: &[String]) -> (Vec<String>, Vec<Token>) {
    let mut leads = Vec::new();
    let mut toks = Vec::new();
    for (li, c) in lines.iter().enumerate() {
        let (lead, t) = tokenize_line(c);
        leads.push(lead);
        for mut tk in t {
            tk.line = li;
            toks.push(tk);
        }
        toks.push(Token { text: "\n".to_string(), line: li, is_nl: true });
    }
    (leads, toks)
}

// ---------------- diff ----------------

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Op { C, R, A }

/// suffix LCS table
fn suffix_lcs(a: &[String], b: &[String]) -> Vec<Vec<usize>> {
    let n = a.len(); let m = b.len();
    let mut l = vec![vec![0usize; m + 1]; n + 1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            l[i][j] = if a[i] == b[j] { l[i + 1][j + 1] + 1 } else { std::cmp::max(l[i + 1][j], l[i][j + 1]) };
        }
    }
    l
}

/// greedy leftmost LCS
pub fn diff(a: &[String], b: &[String]) -> Vec<Op> {
    let n = a.len(); let m = b.len();
    let l = suffix_lcs(a, b);
    let mut ops = Vec::new();
    let mut i = 0; let mut j = 0;
    while i < n && j < m {
        if a[i] == b[j] { ops.push(Op::C); i += 1; j += 1; continue; }
        if l[i][j + 1] == l[i][j] { ops.push(Op::A); j += 1; }
        else { ops.push(Op::R); i += 1; }
    }
    while i < n { ops.push(Op::R); i += 1; }
    while j < m { ops.push(Op::A); j += 1; }
    ops
}

pub fn merge_runs(ops: &[Op]) -> Vec<(Op, usize)> {
    let mut out: Vec<(Op, usize)> = Vec::new();
    for o in ops {
        match out.last_mut() {
            Some((k, c)) if *k == *o => { *c += 1; }
            _ => out.push((*o, 1)),
        }
    }
    out
}

