    if j>=n { return (content.to_string(), Vec::new()); }
    let lead:String=ch[..j].iter().collect();
    let mut toks:Vec<Tok>=Vec::new();
    let mut k=j;
    while k<n {
        let ws=ch[k].is_whitespace(); let l=k;
        while l<n && ch[l].is_whitespace()==ws { l+=1; }
        toks.push(Tok{ text: ch[k..l].iter().collect(), line:0, is_nl:false });
