    for (li,c) in lines.iter().enumerate(){
        let (lead,t)=tokenize_line(c); leads.push(lead);
        for mut tk in t { tk.line=li; toks.push(tk); }
        toks.push(Tok{ text:"\n".to_string(), line:li, is_nl:true });
    }
    (leads,toks)
}

// ---------- diff ----------
#[derive(Clone,Copy,PartialEq,Debug)] enum Op{C,R,A}
#[derive(Clone,Copy,PartialEq,Debug)] enum Kind{Common,Unique}

fn suffix_lcs(a:&[String],b:&[String])->Vec<Vec<usize>>{
    let n=a.len(); let m=b.len();
    let mut l=vec![vec![0usize;m+1];n+1];
    for i in (0..n).rev(){ for j in (0..m).rev(){
        l[i][j]= if a[i]==b[j] { l[i+1][j+1]+1 } else { std::cmp::max(l[i+1][j],l[i][j+1]) };
    }}
    l
}

fn diff(a:&[String],b:&[String])->Vec<Op>{
    let n=a.len(); let m=b.len();
    let l=suffix_lcs(a,b);
    let mut ops=Vec::new(); let mut i=0; let mut j=0;
    while i<n && j<m {
        if a[i]==b[j] { ops.push(Op::C); i+=1; j+=1; continue; }
        if l[i][j+1]==l[i][j] { ops.push(Op::A); j+=1; } else { ops.push(Op::R); i+=1; }
    }
    while i<n { ops.push(Op::R); i+=1; }
    while j<m { ops.push(Op::A); j+=1; }
    ops
}

fn merge_runs(ops:&[Op])->Vec<(Op,usize)>{
    let mut out:Vec<(Op,usize)>=Vec::new();
    for o in ops { match out.last_mut(){ Some((k,c)) if *k==*o =>{*c+=1;}, _=>out.push((*o,1)) } }
    out
}

#[derive(Clone,Debug)] struct Segment{ kind:Kind, text:String }

fn emit_pieces(toks:&[Tok],idx:usize,cnt:usize,kind:Kind,pieces:&mut Vec<(bool,usize,Kind,String)>,removed:bool)->usize{
    let mut buf=String::new();
    let mut curline= if idx<toks.len(){toks[idx].line}else{0};
    let mut i=idx;
    for _ in 0..cnt {
        let t=&toks[i];
        if t.is_nl { pieces.push((removed,curline,kind,buf.clone())); buf.clear(); curline=t.line+1; }
        else { buf.push_str(&t.text); curline=t.line; }
        i+=1;
    }
    if !buf.is_empty(){ pieces.push((removed,curline,kind,buf)); }
    i
}

fn build_segments(toks_r:&[Tok],nr:usize,toks_a:&[Tok],na:usize,ops:&[(Op,usize)])
 ->(Vec<Vec<Segment>>,Vec<Vec<Segment>>){
    let mut pieces:Vec<(bool,usize,Kind,String)>=Vec::new();
    let mut ia=0; let mut ib=0;
    for (op,cnt) in ops {
        match op {
            Op::C=>{ ia=emit_pieces(toks_r,ia,*cnt,Kind::Common,&mut pieces,true);
                     ib=emit_pieces(toks_a,ib,*cnt,Kind::Common,&mut pieces,false); },
            Op::R=>{ ia=emit_pieces(toks_r,ia,*cnt,Kind::Unique,&mut pieces,true); },
            Op::A=>{ ib=emit_pieces(toks_a,ib,*cnt,Kind::Unique,&mut pieces,false); },
        }
    }
    let mut segr:Vec<Vec<Segment>>=vec![Vec::new();nr];
    let mut sega:Vec<Vec<Segment>>=vec![Vec::new();na];
    for (removed,line,kind,text) in pieces {
        let lst= if removed {&mut segr}else{&mut sega};
        if line<lst.len(){
            let l=&mut lst[line];
            if let Some(last)=l.last_mut(){ if last.kind==kind { last.text.push_str(&text); continue; } }
            l.push(Segment{kind,text});
        }
    }
    (segr,sega)
}

// ---------- printing ----------
#[derive(Clone,Copy,PartialEq)] enum Style { Compact, Aligned, Fixed }

struct Out<'a>{ faces:&'a [Face;4], w: Write,
    style: Option<Style>, width: usize }
impl<'a> Out<'a> {
    fn seg(&mut self, face:&Face, text:&str){ let _=&self.w; }
}

fn digits(n:usize)->usize{ let mut d=1; let mut x=n/10; while x>0 { d+=1; x/=10; } d }

fn fmt_width(n:usize, w:usize)->String{ format!("{:>w$}", n, w=w) }

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut faces = default_faces();
    let mut style: Option<Style> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "-h" | "--help" => { print!("{}", help_long()); std::process::exit(0); }
            "-V" | "--version" => { println!("diffr {}", version()); std::process::exit(0); }
            "--colors" => {
                if i+1 >= args.len() { eprintln!("option requires an argument: '--colors'"); print_usage_short_err(); std::process::exit(2); }
                i += 1;
                if let Err(e)=parse_spec(&args[i], &mut faces){ eprintln!("{}", e); std::process::exit(255); }
            }
            "--line-numbers" => {
                if i+1 < args.len() {
                    i += 1;
                    match args[i].as_str() {
                        "compact"=>style=Some(Style::Compact),
                        "aligned"=>style=Some(Style::Aligned),
                        "fixed"=>style=Some(Style::Fixed),
                        other=>{ eprintln!("unexpected line number style: got '{}', expected aligned|compact|fixed", other); std::process::exit(255); }
                    }
                } else { style = Some(Style::Compact); }
            }
            other => { eprintln!("bad argument: '{}'", other); print_usage_short_err(); std::process::exit(2); }
        }
        i += 1;
    }

    let mut input = String::new();
    let _ = std::io::stdin().read_to_string(&mut input);
    let stdout = std::io::stdout();
    let mut w = stdout.lock();
    let _ = run(&input, &faces, style, &mut w);
}

fn run(faces:&[Face;4], style:Option<Style>) -> Result<(),String>{ unimplemented!() }

fn version()->&'static str{ "0.1.5" }

fn help_long()->String{ format!("{}", include_str!("../assets/help.txt")) }
fn usage_short()->&'static str{ include_str!("../assets/h.txt") }

fn print_usage_short_err(){ eprint!("{}", usage_short().replace("$VERSION", version())); }
RSEOF
echo done"}

